283			lane: 'migrated',
284			pass: 1,
285			laneRoot,
286			receiptRoot: join(stageRoot, 'restoration-receipt'),
287		})) as WitnessAngularTinyTranslatorRun;
288		const restoredBehaviorDigest = witnessAngularTinyTranslatorBehaviorDigest(restored);
289		if (restoredBehaviorDigest !== behaviorDigest)
290			throw new Error('TinyTranslator restored browser behavior differs');
291		return {
292			failure: 'witness-semantic-assertion',
293			intendedFailure: true,
294			lane: 'migrated',
295			seam: TINY_TRANSLATOR_MUTATION_SEAM,
296			path: relative(laneRoot, target.path),
297			offset: target.offset,
298			beforeSha256,
299			mutatedSha256,
300			afterRestoreSha256,
301			restoredByteIdentically: true,
