421				backend: 'none',
422				stubbed: false,
423				survivesOnlineReload: true,
424			},
425			routeShape: WITNESS_ANGULAR_TINY_TRANSLATOR_ROUTE_SHAPE,
426			scrollAbsence: runs[0]!.scrollAbsence,
427			accommodations: WITNESS_ANGULAR_TINY_TRANSLATOR_ACCOMMODATIONS,
428			readiness: {
429				angularLineage: { ready: 1, total: 4, counted: false },
430				overall: { ready: 3, total: 12 },
431			},
432			locality: {
433				mode: 'offline',
434				successfulNonLoopback: 0,
435				osWideIsolation: false,
436				mockedNonLoopbackSeams: migrated.mockedNonLoopbackSeams.category.length,
437			},
438			nonclaims: [...WITNESS_ANGULAR_TINY_TRANSLATOR_NONCLAIMS],
439			integrity: { algorithm: 'sha256', canonicalDigest: '' },
440		};
441		receipt.integrity.canonicalDigest = witnessAngularTinyTranslatorDigest(receipt);
442		parseWitnessAngularTinyTranslatorReceipt(receipt);
443		await mkdir(witnessEvidence, { recursive: true });
444		const canonical = canonicalize(receipt);
445		/**
446		 * The companion is rendered from the receipt as PUBLISHED rather than from
447		 * the object in memory: canonicalization sorts keys, so a companion rendered
448		 * from the in-memory object would disagree with the same companion rendered
449		 * from the file, and `verify` — which only ever has the file — would be
450		 * right to reject it.
451		 */
452		const published = parseWitnessAngularTinyTranslatorReceipt(JSON.parse(canonical));
453		await writeFile(join(witnessEvidence, 'receipt.json'), `${canonical}\n`, { flag: 'wx' });
454		await writeFile(
455			join(witnessEvidence, 'receipt.md'),
456			renderWitnessAngularTinyTranslatorReceipt(published),
457			{ flag: 'wx' },
458		);
459		return published;
460	}
461	
462	export async function verifyWitnessAngularTinyTranslator(
463		output = witnessEvidence,
464	): Promise<WitnessAngularTinyTranslatorReceipt> {
465		const expectedProvenance = await verifyLinkedWitnessProvenance(root);
466		const receipt = parseWitnessAngularTinyTranslatorReceipt(
467			JSON.parse(await readFile(join(output, 'receipt.json'), 'utf8')),
468		);
469		if (canonicalize(receipt.provenance) !== canonicalize(expectedProvenance))
470			throw new Error('TinyTranslator linked Witness provenance differs');
471		for (const bound of receipt.canonicalReceipts)
472			if (sha256(await readFile(join(root, bound.path))) !== bound.sha256)
473				throw new Error(`TinyTranslator bound build receipt bytes drifted: ${bound.path}`);
474		if (
475			(await readFile(join(output, 'receipt.md'), 'utf8')) !==
476			renderWitnessAngularTinyTranslatorReceipt(receipt)
477		)
478			throw new Error('TinyTranslator human Witness receipt differs');
479		const serialized = canonicalize(receipt);
480		if (serialized.includes(root) || serialized.includes(process.env.USER ?? ''))
481			throw new Error('TinyTranslator receipt leaks host identity');
482		return receipt;
483	}
484	
485	export async function main(args = process.argv.slice(2)): Promise<void> {
486		const publishIndex = args.indexOf('--publish');
487		const verifyIndex = args.indexOf('--verify');
488		if (args.includes('--run-twice') && publishIndex >= 0 && args[publishIndex + 1]) {
489			const output = resolve(root, args[publishIndex + 1]!);
490			if (output !== witnessEvidence) throw new Error('TinyTranslator publish path differs');
491			const receipt = await runWitnessAngularTinyTranslator();
492			process.stdout.write(
493				`${canonicalize({ result: receipt.result, digest: receipt.integrity.canonicalDigest })}\n`,
494			);
495			return;
496		}
497		if (verifyIndex >= 0 && args[verifyIndex + 1]) {
498			const receipt = await verifyWitnessAngularTinyTranslator(
499				resolve(root, args[verifyIndex + 1]!),
500			);
501			process.stdout.write(
502				`${canonicalize({ result: receipt.result, digest: receipt.integrity.canonicalDigest })}\n`,
503			);
504			return;
505		}
506		throw new Error(
507			'TinyTranslator Witness runner requires --run-twice --publish <dir> or --verify <dir>',
508		);
509	}
510	
511	if (basename(process.argv[1] ?? '') === 'angular-tiny-translator-run.ts')
512		main().catch((error: unknown) => {
513			process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
514			process.exitCode = 1;
515		});
