const angularTinyTranslatorSpec: AppSpec = {
	app: ANGULAR_TINY_TRANSLATOR_APP,
	framework: 'angular',
	canonicalReceipt: 'evidence/runs/angular-tiny-translator-v0-12-0/u17d-final-green-lane.json',
