		expect(spec.app).toBe(ANGULAR_TINY_TRANSLATOR_APP);
		expect(spec.framework).toBe('angular');
		const bound = Object.fromEntries(
			ANGULAR_TINY_TRANSLATOR_CANONICAL_RECEIPTS.map((receipt) => [
				receipt.lane,
				receipt.canonicalRoot,
			]),
		);
